  "journal": "American journal of kidney diseases : the official journal of the National Kidney Foundation",
  "doi": "10.1053/j.ajkd.2019.12.001",
  "pmid": "32778223",
  "url": "https://pubmed.ncbi.nlm.nih.gov/32778223/",
  "pubdate": "2020-04",
